INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"53ee6a39-6959-53c2-a5d1-99cc2c7daf85","title":"Business Studies · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 10","questions":[{"question":"Customers complain about long queues. What should the business do first in a structured problem-solving process?","options":["Buy equipment before checking causes","Blame customers immediately","Copy a random competitor without analysis","Define and investigate the queue problem"],"correct_index":3,"explanation":"A clear problem definition and evidence help identify causes. Solutions should address the cause rather than a guessed symptom.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which slide design best supports a short business presentation?","options":["A dense page of tiny text","Unlabelled figures with no source","A readable chart with a clear label and explained message","Animated text that hides the main point"],"correct_index":2,"explanation":"Visuals should make evidence easier to interpret. Explain units, meaning and source rather than expecting decoration to communicate the argument.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A manager allocates tasks using stereotypes about gender. Why is this harmful?","options":["It is always the most accurate skills test","It can unfairly exclude capable people and damage trust","It guarantees teamwork","It makes individual skills irrelevant"],"correct_index":1,"explanation":"Fair task allocation should consider skills and development needs. Stereotyping undermines inclusion and team performance.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which action best handles a disagreement about a deadline?","options":["Insult the other member","Hide the deadline","Listen to both views and agree a practical plan tied to the goal","Refuse to discuss evidence"],"correct_index":2,"explanation":"Constructive conflict management focuses on the issue, evidence and achievable agreements, with follow-up responsibilities.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A team meets its deadline but one member did nearly all the work. Which evaluation best supports improvement?","options":["A met deadline proves teamwork was effective in every respect.","Punish every member identically without hearing them.","Review both the output and the fairness of roles, communication and contribution.","Remove all role allocation from the next project."],"correct_index":2,"explanation":"Performance includes process as well as output. Evidence about contributions and barriers helps redistribute tasks fairly and improve communication while recognising the completed result.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","bst"],"metadata":{"term":2,"focus":"Mixed revision: Problem solving, research and business plans; Relationships and team performance","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"554bf87a-c319-57bf-90fc-41484275f9d0","title":"Business Studies · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 10","questions":[{"question":"A bakery turns flour into bread. Which economic sector describes this production?","options":["Primary","Tertiary","Secondary","Public sector only"],"correct_index":2,"explanation":"The secondary sector transforms raw materials into products. Farming wheat is primary; selling services is tertiary.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can unemployment affect a local shop's sales?","options":["It guarantees higher sales for every shop","Lower household income can reduce demand","It eliminates all business costs","It changes a shop into a primary-sector business"],"correct_index":1,"explanation":"Unemployment can reduce customers' spending power. Businesses should examine local evidence and demand patterns rather than assume identical effects everywhere.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A manager allocates tasks using stereotypes about gender. Why is this harmful?","options":["It is always the most accurate skills test","It can unfairly exclude capable people and damage trust","It guarantees teamwork","It makes individual skills irrelevant"],"correct_index":1,"explanation":"Fair task allocation should consider skills and development needs. Stereotyping undermines inclusion and team performance.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which action best handles a disagreement about a deadline?","options":["Insult the other member","Hide the deadline","Listen to both views and agree a practical plan tied to the goal","Refuse to discuss evidence"],"correct_index":2,"explanation":"Constructive conflict management focuses on the issue, evidence and achievable agreements, with follow-up responsibilities.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A team meets its deadline but one member did nearly all the work. Which evaluation best supports improvement?","options":["A met deadline proves teamwork was effective in every respect.","Punish every member identically without hearing them.","Review both the output and the fairness of roles, communication and contribution.","Remove all role allocation from the next project."],"correct_index":2,"explanation":"Performance includes process as well as output. Evidence about contributions and barriers helps redistribute tasks fairly and improve communication while recognising the completed result.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","bst"],"metadata":{"term":3,"focus":"Mixed revision: Business sectors and ownership; Relationships and team performance","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"500135dd-dfa5-5d3d-9974-1f750fbe0d32","title":"Business Studies · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 10","questions":[{"question":"A bakery turns flour into bread. Which economic sector describes this production?","options":["Primary","Tertiary","Secondary","Public sector only"],"correct_index":2,"explanation":"The secondary sector transforms raw materials into products. Farming wheat is primary; selling services is tertiary.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can unemployment affect a local shop's sales?","options":["It guarantees higher sales for every shop","Lower household income can reduce demand","It eliminates all business costs","It changes a shop into a primary-sector business"],"correct_index":1,"explanation":"Unemployment can reduce customers' spending power. Businesses should examine local evidence and demand patterns rather than assume identical effects everywhere.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which example is primary market research?","options":["Surveying the shop's customers directly","Reading last year's published industry report","Copying a newspaper statistic","Using an old public census table"],"correct_index":0,"explanation":"Primary research collects new data for the current purpose. Published existing information is secondary research.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why include a cash-flow forecast in a business plan?","options":["To guarantee every sale is cash","To anticipate when cash may be received and paid","To replace a description of customers","To prove the business cannot fail"],"correct_index":1,"explanation":"Timing matters: a profitable business can still run short of cash. A forecast supports planning, not certainty.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A shop surveys only customers who bought immediately about long queues. Why might its proposed solution be weak?","options":["Purchasers necessarily represent everyone who left.","A larger logo would remove sampling bias.","It excludes people who left without buying, whose experiences may reveal the main problem.","Primary research is never useful."],"correct_index":2,"explanation":"The sample omits affected non-buyers and may underestimate queue-related lost sales. Include these customers where feasible and compare observations of waiting times before selecting a remedy.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","bst"],"metadata":{"term":4,"focus":"Mixed revision: Business sectors and ownership; Problem solving, research and business plans","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=wLnynjhDg3w%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"dfa8fd24-042b-5487-af5e-edc0cf6d59c6","title":"Economics · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 10","questions":[{"question":"What is a main benefit of a generally accepted medium of exchange over barter?","options":["It reduces the need for a double coincidence of wants","It eliminates all scarcity","It guarantees equal incomes","It prevents any price changes"],"correct_index":0,"explanation":"Money allows people to sell to one person and buy from another without each wanting exactly the other's goods.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which action is part of collective bargaining?","options":["Customers choose a shop's logo","A firm hides wages from every worker","A worker guesses the inflation rate","Worker representatives and employers negotiate employment conditions"],"correct_index":3,"explanation":"Collective bargaining involves representatives negotiating employment matters. Its outcomes depend on the process and applicable framework.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which situation best illustrates structural unemployment?","options":["A worker voluntarily takes one lunch break","All vacancies are filled instantly","Workers' skills do not match the jobs available after industry changes","A firm changes its stationery colour"],"correct_index":2,"explanation":"Structural unemployment involves a mismatch between labour supply and demand, including skills or location. Retraining may be part of a response.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why might public works programmes help address unemployment?","options":["They guarantee permanent jobs for everyone","They eliminate the need for training","They make project quality irrelevant","They can provide temporary paid work and useful infrastructure"],"correct_index":3,"explanation":"Public works can provide income and assets while broader employment measures develop. Their scale, duration and training content affect their impact.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A labour force has 800 employed and 200 unemployed. Fifty unemployed people stop seeking work and leave this defined labour force. What happens to the rate?","options":["It stays 20% because population cannot change.","It falls to 0% because all unemployment ended.","It falls to about 15.8%, although no additional person got a job.","It rises to 25% because jobs were created."],"correct_index":2,"explanation":"Using the stated labour-force definition, unemployment is now 150 and labour force 950: 150/950≈15.8%. The fall reflects withdrawal rather than job creation, so interpretation matters.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","eco"],"metadata":{"term":2,"focus":"Mixed revision: Development, population and labour; Unemployment and economic redress","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"b8936851-aa98-58c4-b536-4f2595f6eee9","title":"Economics · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 10","questions":[{"question":"If demand rises while supply is unchanged, what happens to equilibrium price in the standard model?","options":["It necessarily falls","It must stay identical","It becomes zero","It rises"],"correct_index":3,"explanation":"A rightward demand shift raises equilibrium price and quantity, other things equal. Distinguish a shift from movement along a demand curve.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why do economic choices have opportunity costs?","options":["All goods are free","Resources are unlimited","Choosing one option can mean giving up the next best alternative","Money is the only scarce resource"],"correct_index":2,"explanation":"Scarcity creates trade-offs. Opportunity cost is the value of the next best alternative forgone, which need not be a cash payment.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which situation best illustrates structural unemployment?","options":["A worker voluntarily takes one lunch break","All vacancies are filled instantly","Workers' skills do not match the jobs available after industry changes","A firm changes its stationery colour"],"correct_index":2,"explanation":"Structural unemployment involves a mismatch between labour supply and demand, including skills or location. Retraining may be part of a response.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why might public works programmes help address unemployment?","options":["They guarantee permanent jobs for everyone","They eliminate the need for training","They make project quality irrelevant","They can provide temporary paid work and useful infrastructure"],"correct_index":3,"explanation":"Public works can provide income and assets while broader employment measures develop. Their scale, duration and training content affect their impact.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A labour force has 800 employed and 200 unemployed. Fifty unemployed people stop seeking work and leave this defined labour force. What happens to the rate?","options":["It stays 20% because population cannot change.","It falls to 0% because all unemployment ended.","It falls to about 15.8%, although no additional person got a job.","It rises to 25% because jobs were created."],"correct_index":2,"explanation":"Using the stated labour-force definition, unemployment is now 150 and labour force 950: 150/950≈15.8%. The fall reflects withdrawal rather than job creation, so interpretation matters.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","eco"],"metadata":{"term":3,"focus":"Mixed revision: Markets, intervention and scarcity; Unemployment and economic redress","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"8a6beb19-f3a0-5eef-aae4-46699eb024ea","title":"Economics · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 10","questions":[{"question":"If demand rises while supply is unchanged, what happens to equilibrium price in the standard model?","options":["It necessarily falls","It must stay identical","It becomes zero","It rises"],"correct_index":3,"explanation":"A rightward demand shift raises equilibrium price and quantity, other things equal. Distinguish a shift from movement along a demand curve.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why do economic choices have opportunity costs?","options":["All goods are free","Resources are unlimited","Choosing one option can mean giving up the next best alternative","Money is the only scarce resource"],"correct_index":2,"explanation":"Scarcity creates trade-offs. Opportunity cost is the value of the next best alternative forgone, which need not be a cash payment.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A country has 40 births and 25 deaths per 1 000 people, ignoring migration. Find its natural increase per 1 000.","options":["65","15","25","40"],"correct_index":1,"explanation":"Natural increase = birth rate−death rate = 40−25=15 per 1 000. Migration is a separate component of population change.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why is education relevant to labour productivity?","options":["It guarantees every worker a job","It makes equipment unnecessary","It can develop knowledge and skills that improve output per worker","It eliminates differences between all occupations"],"correct_index":2,"explanation":"Human-capital development can support productivity, alongside health, technology and work organisation. It does not by itself guarantee employment.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Training raises output per worker, but employment does not immediately rise. Which conclusion is justified?","options":["Training must have failed because employment was unchanged.","Output per worker and worker numbers are the same measure.","Productivity can improve without a simultaneous increase in the number employed.","The result proves training always reduces employment."],"correct_index":2,"explanation":"Productivity concerns output relative to inputs, not simply the number of jobs. Demand, investment and business conditions also influence hiring, so separate these indicators when evaluating the programme.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","eco"],"metadata":{"term":4,"focus":"Mixed revision: Markets, intervention and scarcity; Development, population and labour","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=2YOyPh4gQKY%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"0a5da9d9-7a0c-5c7b-b878-2689bf55695e","title":"Geography · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 10","questions":[{"question":"A district has 60 000 people in 200 km². Find its population density.","options":["3 people/km²","300 people/km²","12 000 000 people/km²","30 people/km²"],"correct_index":1,"explanation":"Population density = population/area = 60 000/200 = 300 people per km². An average can hide uneven distribution.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Why can rural–urban migration create planning challenges?","options":["Services and housing may need to expand rapidly","It automatically reduces all urban populations","It eliminates transport demand","It means every migrant has the same experience"],"correct_index":0,"explanation":"Rapid population change can increase demand for housing, water, transport and jobs. Planning should consider varied needs and contributions.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Which action most directly supports sustainable school water use?","options":["Leave taps running to test the pipes","Ignore meter readings","Use treated drinking water for every unnecessary task","Repair leaks and monitor consumption"],"correct_index":3,"explanation":"Fixing leaks reduces avoidable losses. Monitoring shows whether savings persist and helps detect new problems.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why protect vegetation in a river catchment?","options":["It can slow runoff, support infiltration and reduce erosion","It guarantees no flood can ever occur","It prevents all water reaching rivers","It creates unlimited rainfall"],"correct_index":0,"explanation":"Vegetation helps regulate water movement and stabilise soil. Flood risk also depends on storm intensity, saturation and land use.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"A town proposes a higher river wall as its only flood measure. Which appraisal is most complete?","options":["Assume any wall eliminates every future flood.","Ignore upstream land use because rivers are isolated at town borders.","Assess the wall alongside upstream runoff, floodplain exposure, maintenance and warning systems.","Move warnings to after flood damage is recorded."],"correct_index":2,"explanation":"Flood risk depends on catchment processes, infrastructure and exposure. A combined appraisal considers effectiveness, displaced risk and maintenance rather than treating one structure as a universal solution.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","geo"],"metadata":{"term":2,"focus":"Mixed revision: Population geography and migration; Water management and flooding","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"7053626e-7b19-5141-be1a-425706486b22","title":"Geography · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 10","questions":[{"question":"At a constructive plate boundary, plates generally…","options":["Move apart and new crust can form","Move towards one another in every case","Remain completely motionless","Stop all volcanic activity"],"correct_index":0,"explanation":"Divergent plate movement can allow magma to rise and solidify as new crust. Identify the boundary type before predicting processes.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why can similar earthquakes cause different losses in two cities?","options":["Magnitude is the only possible factor","Population and infrastructure never matter","All earthquakes cause identical damage","Exposure, building quality and preparedness differ"],"correct_index":3,"explanation":"Risk depends on the hazard plus vulnerability and exposure. Safer buildings and preparation can reduce losses without preventing earthquakes.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Which action most directly supports sustainable school water use?","options":["Leave taps running to test the pipes","Ignore meter readings","Use treated drinking water for every unnecessary task","Repair leaks and monitor consumption"],"correct_index":3,"explanation":"Fixing leaks reduces avoidable losses. Monitoring shows whether savings persist and helps detect new problems.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why protect vegetation in a river catchment?","options":["It can slow runoff, support infiltration and reduce erosion","It guarantees no flood can ever occur","It prevents all water reaching rivers","It creates unlimited rainfall"],"correct_index":0,"explanation":"Vegetation helps regulate water movement and stabilise soil. Flood risk also depends on storm intensity, saturation and land use.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"A town proposes a higher river wall as its only flood measure. Which appraisal is most complete?","options":["Assume any wall eliminates every future flood.","Ignore upstream land use because rivers are isolated at town borders.","Assess the wall alongside upstream runoff, floodplain exposure, maintenance and warning systems.","Move warnings to after flood damage is recorded."],"correct_index":2,"explanation":"Flood risk depends on catchment processes, infrastructure and exposure. A combined appraisal considers effectiveness, displaced risk and maintenance rather than treating one structure as a universal solution.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","geo"],"metadata":{"term":3,"focus":"Mixed revision: Plate tectonics and geological hazards; Water management and flooding","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"8d67c2e8-7917-50c8-b387-ddc7837ecb57","title":"Geography · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 10","questions":[{"question":"At a constructive plate boundary, plates generally…","options":["Move apart and new crust can form","Move towards one another in every case","Remain completely motionless","Stop all volcanic activity"],"correct_index":0,"explanation":"Divergent plate movement can allow magma to rise and solidify as new crust. Identify the boundary type before predicting processes.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why can similar earthquakes cause different losses in two cities?","options":["Magnitude is the only possible factor","Population and infrastructure never matter","All earthquakes cause identical damage","Exposure, building quality and preparedness differ"],"correct_index":3,"explanation":"Risk depends on the hazard plus vulnerability and exposure. Safer buildings and preparation can reduce losses without preventing earthquakes.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"What may a broad base on a population pyramid suggest?","options":["Every resident is elderly","No births have occurred","A large proportion of young people","All age groups have equal numbers"],"correct_index":2,"explanation":"The base represents younger ages. Interpret the full pyramid and data context before predicting future growth.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Which is a push factor for migration?","options":["Better jobs at the destination","Safer housing at the destination","Access to a desired university elsewhere","Loss of local employment"],"correct_index":3,"explanation":"Push factors encourage departure from an origin. Pull factors attract people towards a destination.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"A district's density is 300 people/km². A planner concludes every square kilometre contains exactly 300 people. What is wrong?","options":["Density states every household has 300 members.","Averages can only be used for temperature.","Density is an average; settlement can be uneven within the district.","The land area must equal the population."],"correct_index":2,"explanation":"Total population divided by area gives an average, not a uniform distribution. Maps of settlement and land use are needed to plan local services.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","geo"],"metadata":{"term":4,"focus":"Mixed revision: Plate tectonics and geological hazards; Population geography and migration","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=N1lYOPiWGvI%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"c6290a97-6386-59db-9399-ad1b7212a778","title":"History · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"History","grade":"Grade 10","questions":[{"question":"What was one effect of colonial expansion into the interior of southern Africa?","options":["An end to every conflict","Equal political rights for all inhabitants","Changes to land control and labour relations","No effect on local societies"],"correct_index":2,"explanation":"Expansion affected land, labour, political authority and resistance. Effects varied across places and communities and should be supported with examples.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What is a sound historical paragraph?","options":["A list of unrelated dates","A clear point supported by relevant evidence and explanation","An opinion with no evidence","A copied source with no interpretation"],"correct_index":1,"explanation":"Link the point, evidence and reasoning to the question. Evidence matters because it supports, qualifies or challenges the argument.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why is Sol Plaatje's writing useful for studying the 1913 land law?","options":["It records an informed contemporary critique and experiences of its effects","It is automatically free of viewpoint","It replaces every other source","It proves every person had the same experience"],"correct_index":0,"explanation":"Plaatje offers valuable contemporary evidence. Evaluate his purpose and corroborate specific claims rather than treating any source as complete.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What does corroborating a source mean?","options":["Copying its wording twice","Checking its claims against other relevant evidence","Ignoring its date","Assuming agreement proves perfect truth"],"correct_index":1,"explanation":"Corroboration compares evidence for support or contradiction. Independent sources and context help assess reliability.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An essay claims the 1913 land law had identical effects on every African family immediately. What would strengthen the argument?","options":["Repeat the word identical without additional evidence.","Use only the law's title as proof of every outcome.","Examine varied regional and household experiences and qualify the scope of change.","Ignore experiences that complicate the claim."],"correct_index":2,"explanation":"Legislation and implementation can affect groups differently. A strong historical judgement relates the law's racial restrictions to evidence of actual outcomes and acknowledges variation.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","hist"],"metadata":{"term":2,"focus":"Mixed revision: Colonial expansion, war and Union; The 1913 land law and examination skills","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"c4caa8d1-f985-5430-8945-800b68a8f8dc","title":"History · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"History","grade":"Grade 10","questions":[{"question":"Which condition contributed to revolutionary pressures in France before 1789?","options":["Universal equal taxation already accepted by all","Financial crisis and unequal burdens within the estate system","The absence of political conflict","A fully democratic republic for centuries"],"correct_index":1,"explanation":"Fiscal crisis, privilege, inequality and new political ideas contributed to tensions. A strong answer explains their interaction rather than listing only one cause.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why do historians compare accounts of political change in southern Africa after 1750?","options":["Different evidence and perspectives can challenge single-cause explanations","All oral accounts must be discarded","The first published account must always be accepted","Every source gives identical evidence"],"correct_index":0,"explanation":"Comparison and corroboration help evaluate contested interpretations. Consider chronology, context and the strengths and limits of different evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why is Sol Plaatje's writing useful for studying the 1913 land law?","options":["It records an informed contemporary critique and experiences of its effects","It is automatically free of viewpoint","It replaces every other source","It proves every person had the same experience"],"correct_index":0,"explanation":"Plaatje offers valuable contemporary evidence. Evaluate his purpose and corroborate specific claims rather than treating any source as complete.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What does corroborating a source mean?","options":["Copying its wording twice","Checking its claims against other relevant evidence","Ignoring its date","Assuming agreement proves perfect truth"],"correct_index":1,"explanation":"Corroboration compares evidence for support or contradiction. Independent sources and context help assess reliability.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An essay claims the 1913 land law had identical effects on every African family immediately. What would strengthen the argument?","options":["Repeat the word identical without additional evidence.","Use only the law's title as proof of every outcome.","Examine varied regional and household experiences and qualify the scope of change.","Ignore experiences that complicate the claim."],"correct_index":2,"explanation":"Legislation and implementation can affect groups differently. A strong historical judgement relates the law's racial restrictions to evidence of actual outcomes and acknowledges variation.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","hist"],"metadata":{"term":3,"focus":"Mixed revision: French Revolution and historical reasoning; The 1913 land law and examination skills","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"8f730dfa-5fb4-5e02-8c70-1853ff1df4ad","title":"History · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"History","grade":"Grade 10","questions":[{"question":"Which condition contributed to revolutionary pressures in France before 1789?","options":["Universal equal taxation already accepted by all","Financial crisis and unequal burdens within the estate system","The absence of political conflict","A fully democratic republic for centuries"],"correct_index":1,"explanation":"Fiscal crisis, privilege, inequality and new political ideas contributed to tensions. A strong answer explains their interaction rather than listing only one cause.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why do historians compare accounts of political change in southern Africa after 1750?","options":["Different evidence and perspectives can challenge single-cause explanations","All oral accounts must be discarded","The first published account must always be accepted","Every source gives identical evidence"],"correct_index":0,"explanation":"Comparison and corroboration help evaluate contested interpretations. Consider chronology, context and the strengths and limits of different evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why is mining capitalism relevant to studying the South African War?","options":["The war had no economic context","Mining began only after 1994","Every cause can be reduced to one mine owner","Gold, capital and competing political interests shaped tensions"],"correct_index":3,"explanation":"Economic change helps explain tensions, alongside political and imperial factors. Avoid presenting one factor as the only cause.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"A source is a civilian's diary written during a war. What can it reveal especially well?","options":["That individual's experiences and perceptions at the time","A complete neutral account of every battlefield","The intentions of every government leader","The experiences of all civilians without comparison"],"correct_index":0,"explanation":"A diary provides a situated perspective. It may be valuable for lived experience while needing comparison with other sources for broader claims.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"A wartime diary describes food shortages in one household. Which conclusion is strongest?","options":["It proves every household had identical shortages.","A personal source has no historical value.","It provides evidence of that household's experience; wider claims need comparison.","The writer necessarily knew all military decisions."],"correct_index":2,"explanation":"A contemporary diary offers detailed lived experience from a particular perspective. Its reach is limited, so compare other testimonies and records before generalising nationally.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","hist"],"metadata":{"term":4,"focus":"Mixed revision: French Revolution and historical reasoning; Colonial expansion, war and Union","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=kAd8e9PQSxE%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"975f540e-2800-59be-9828-c232726c3da2","title":"Tourism · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Tourism","grade":"Grade 10","questions":[{"question":"Which behaviour best protects a wildlife attraction?","options":["Feed wildlife for photographs","Remove plants as souvenirs","Leave litter near water","Keep a safe distance and follow park rules"],"correct_index":3,"explanation":"Responsible visitors avoid disturbing animals and habitats. Follow local guidance and protect both people and wildlife.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A lodge buys produce from nearby farmers. What benefit can this support?","options":["A guarantee of zero environmental impact","The elimination of all transport","Local economic linkages","An end to every seasonal job"],"correct_index":2,"explanation":"Local purchasing can retain more visitor spending in the area and support suppliers. Sustainability still requires considering quality, fairness and environmental effects.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A guest says their booking is wrong. What is the best first response?","options":["Argue before checking evidence","Listen, clarify the details and check the booking record","Ignore the guest","Promise an impossible outcome immediately"],"correct_index":1,"explanation":"Customer care begins with listening and accurate information. Then explain practical options within the business's authority.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which written message is clearest for a guest?","options":["Come sometime soon.","It is happening there later.","Your tour departs from reception at 08:30 tomorrow; please arrive by 08:15.","You know the plan already."],"correct_index":2,"explanation":"Useful communication specifies action, place and time. Avoid assumptions and invite clarification where needed.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A guide plans a cultural visit without asking hosts how practices should be represented. What improvement is best?","options":["Use stereotypes because they make every visit simpler.","Assume payment permits every photograph and activity.","Consult hosts, obtain appropriate agreement and present accurate context respectfully.","Replace the hosts' account with invented stories."],"correct_index":2,"explanation":"Responsible cultural tourism respects people's agency, context and boundaries. Consultation helps ensure accurate representation and appropriate visitor behaviour rather than imposing assumptions.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","tour"],"metadata":{"term":2,"focus":"Mixed revision: Attractions and responsible tourism; Culture, communication and customer care","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"96454f84-0d16-5c30-a733-99f54a216e55","title":"Tourism · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Tourism","grade":"Grade 10","questions":[{"question":"A traveller visits Durban from their home in Johannesburg. What type of tourism is this?","options":["Inbound international tourism","Outbound international tourism","Domestic tourism","Space tourism"],"correct_index":2,"explanation":"The traveller remains within their own country. Domestic tourism can cross provincial boundaries without becoming international tourism.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can domestic tourism support local economies?","options":["All visitor spending goes abroad automatically","Visitor spending can support businesses, jobs and linked suppliers","It eliminates seasonal changes","It guarantees equal income for every resident"],"correct_index":1,"explanation":"Local spending can create direct and indirect benefits. Who benefits depends on ownership, sourcing and local linkages.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A guest says their booking is wrong. What is the best first response?","options":["Argue before checking evidence","Listen, clarify the details and check the booking record","Ignore the guest","Promise an impossible outcome immediately"],"correct_index":1,"explanation":"Customer care begins with listening and accurate information. Then explain practical options within the business's authority.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which written message is clearest for a guest?","options":["Come sometime soon.","It is happening there later.","Your tour departs from reception at 08:30 tomorrow; please arrive by 08:15.","You know the plan already."],"correct_index":2,"explanation":"Useful communication specifies action, place and time. Avoid assumptions and invite clarification where needed.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A guide plans a cultural visit without asking hosts how practices should be represented. What improvement is best?","options":["Use stereotypes because they make every visit simpler.","Assume payment permits every photograph and activity.","Consult hosts, obtain appropriate agreement and present accurate context respectfully.","Replace the hosts' account with invented stories."],"correct_index":2,"explanation":"Responsible cultural tourism respects people's agency, context and boundaries. Consultation helps ensure accurate representation and appropriate visitor behaviour rather than imposing assumptions.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","tour"],"metadata":{"term":3,"focus":"Mixed revision: Map work and domestic tourism; Culture, communication and customer care","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"fc4a3a04-f351-5be7-857a-dc5593cf392d","title":"Tourism · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Tourism","grade":"Grade 10","questions":[{"question":"A traveller visits Durban from their home in Johannesburg. What type of tourism is this?","options":["Inbound international tourism","Outbound international tourism","Domestic tourism","Space tourism"],"correct_index":2,"explanation":"The traveller remains within their own country. Domestic tourism can cross provincial boundaries without becoming international tourism.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can domestic tourism support local economies?","options":["All visitor spending goes abroad automatically","Visitor spending can support businesses, jobs and linked suppliers","It eliminates seasonal changes","It guarantees equal income for every resident"],"correct_index":1,"explanation":"Local spending can create direct and indirect benefits. Who benefits depends on ownership, sourcing and local linkages.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What are the three commonly used sustainability pillars?","options":["Environmental, social and economic","Advertising, colour and sound","Only profit, profit and profit","Transport, passports and luggage"],"correct_index":0,"explanation":"Sustainable tourism considers ecosystems, communities and economic viability together. A project can succeed financially while causing other harms.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why should marketing identify a target market?","options":["One message always suits everyone equally","Different visitors have different needs, budgets and interests","It removes the need to research customers","It guarantees every advertisement will succeed"],"correct_index":1,"explanation":"A defined market helps choose relevant products, messages and channels. Test assumptions through research and feedback.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A lodge calls itself sustainable because it buys local produce, but it wastes water and excludes local residents from decisions. Which evaluation is strongest?","options":["One local purchase proves complete sustainability.","Water use has no place in tourism evaluation.","Local sourcing is a benefit, but environmental and social practices also need assessment.","Community participation cannot affect tourism."],"correct_index":2,"explanation":"Sustainability includes environmental, social and economic dimensions. Assess actual sourcing, resource use and community participation before accepting the broad marketing claim.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","tour"],"metadata":{"term":4,"focus":"Mixed revision: Map work and domestic tourism; Attractions and responsible tourism","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=rZVthqmlBvM%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}}]$smartbridge$::jsonb)
